export default async function Home() {
  let health = null;
  let error = null;

  try {
    const res = await fetch("http://localhost:3000/api/health", {
      cache: "no-store",
    });
    health = await res.json();
  } catch (e) {
    error = e?.message ?? String(e);
  }

  return (
    <div className="p-10">
      <h1 className="text-4xl font-bold">TruLabel Frontend ✅</h1>
      <p className="mt-4 text-zinc-600">
        If this text looks styled, Tailwind is working.
      </p>

      <div className="mt-8 rounded-xl border border-zinc-800 bg-zinc-950 p-4">
        <div className="font-semibold">Backend /api/health</div>

        {error ? (
          <p className="mt-2 text-red-400">Error: {error}</p>
        ) : (
          <pre className="mt-2 overflow-auto text-sm text-zinc-200">
            {JSON.stringify(health, null, 2)}
          </pre>
        )}
      </div>
    </div>
  );
}
